/*
 * atg_kc705_pcie: The KC705's PCIe endpoint (ws288 p013, docs/ghci.md
 * section 15.2): the AXI Memory Mapped To PCI Express bridge (Gen2 x4,
 * 128-bit AXI in its axi_aclk_out, 125 MHz = user_clk) and the AXI cores
 * around it, generated by boards/kc705/ip.tcl (not committed):
 *
 *   atg_kc705_pcie_ip   the bridge: BAR0 (128 KiB) -> AXI 0x0000_0000,
 *                       BAR2 (64 MiB) -> AXI 0x8000_0000; MSI (1
 *                       vector); S_AXI the AXI -> PCIe side.
 *   atg_kc705_bar_xbar  the bridge's master to M00 (BAR0) and M01 (BAR2),
 *                       DECERR elsewhere.
 *   atg_kc705_bar0_dn   M00 128 -> 32 bit.
 *
 * Ports for the board top: m0_* the register window (32-bit, offsets
 * 16:0, ID 0), m2_* the local window (128-bit, offsets 25:0), s_* the
 * GPU's host accesses (AXI -> PCIe, ID 4; version 1 drives nothing on
 * it), msi_req/msi_ack: the message of GHCI's one vector is requested
 * (msi_req held) and msi_ack pulses when the bridge granted it
 * (INTX_MSI_Request held until INTX_MSI_Grant; vector number 0).  user_rst_n: perst_n and the bridge's MMCM
 * lock, synchronised to user_clk.  The bridge's control slave (s_axi_ctl)
 * is unused (ready, OKAY, reads 0).  The bridge's handshake details
 * (INTX_MSI_*, axi_aresetn) are from its port list, PG055 not read
 * (Unverified).  In simulation this module is replaced by
 * sim/models/kc705/atg_kc705_pcie.v (same name and ports).
 * See spec/boards/kc705/lib/atg_kc705_pcie.md.
 */

`timescale 1ns / 1ps
`default_nettype none

module atg_kc705_pcie (
	input wire pcie_refclk_p,
	input wire pcie_refclk_n,
	input wire pcie_perst_n,
	output wire [3:0] pcie_txp,
	output wire [3:0] pcie_txn,
	input wire [3:0] pcie_rxp,
	input wire [3:0] pcie_rxn,
	output wire user_clk,
	output wire user_rst_n,
	output wire link_up,
	/* BAR0: the register window */
	output wire [16:0] m0_awaddr,
	output wire [3:0] m0_awid,
	output wire m0_awvalid,
	input wire m0_awready,
	output wire [31:0] m0_wdata,
	output wire [3:0] m0_wstrb,
	output wire m0_wlast,
	output wire m0_wvalid,
	input wire m0_wready,
	input wire [3:0] m0_bid,
	input wire [1:0] m0_bresp,
	input wire m0_bvalid,
	output wire m0_bready,
	output wire [16:0] m0_araddr,
	output wire [3:0] m0_arid,
	output wire [7:0] m0_arlen,
	output wire m0_arvalid,
	input wire m0_arready,
	input wire [31:0] m0_rdata,
	input wire [3:0] m0_rid,
	input wire [1:0] m0_rresp,
	input wire m0_rlast,
	input wire m0_rvalid,
	output wire m0_rready,
	/* BAR2: the local window */
	output wire [25:0] m2_awaddr,
	output wire [3:0] m2_awid,
	output wire [7:0] m2_awlen,
	output wire [2:0] m2_awsize,
	output wire [1:0] m2_awburst,
	output wire m2_awvalid,
	input wire m2_awready,
	output wire [127:0] m2_wdata,
	output wire [15:0] m2_wstrb,
	output wire m2_wlast,
	output wire m2_wvalid,
	input wire m2_wready,
	input wire [3:0] m2_bid,
	input wire [1:0] m2_bresp,
	input wire m2_bvalid,
	output wire m2_bready,
	output wire [25:0] m2_araddr,
	output wire [3:0] m2_arid,
	output wire [7:0] m2_arlen,
	output wire [2:0] m2_arsize,
	output wire [1:0] m2_arburst,
	output wire m2_arvalid,
	input wire m2_arready,
	input wire [127:0] m2_rdata,
	input wire [3:0] m2_rid,
	input wire [1:0] m2_rresp,
	input wire m2_rlast,
	input wire m2_rvalid,
	output wire m2_rready,
	/* GPU -> host memory */
	input wire [31:0] s_awaddr,
	input wire [3:0] s_awid,
	input wire [7:0] s_awlen,
	input wire [2:0] s_awsize,
	input wire [1:0] s_awburst,
	input wire s_awvalid,
	output wire s_awready,
	input wire [127:0] s_wdata,
	input wire [15:0] s_wstrb,
	input wire s_wlast,
	input wire s_wvalid,
	output wire s_wready,
	output wire [3:0] s_bid,
	output wire [1:0] s_bresp,
	output wire s_bvalid,
	input wire s_bready,
	input wire [31:0] s_araddr,
	input wire [3:0] s_arid,
	input wire [7:0] s_arlen,
	input wire [2:0] s_arsize,
	input wire [1:0] s_arburst,
	input wire s_arvalid,
	output wire s_arready,
	output wire [127:0] s_rdata,
	output wire [3:0] s_rid,
	output wire [1:0] s_rresp,
	output wire s_rlast,
	output wire s_rvalid,
	input wire s_rready,
	/* MSI */
	input wire msi_req,
	output wire msi_ack
);
	wire refclk, aclk, ctl_aclk, mmcm_lock, intx_grant, msi_en, irq_out;
	wire [2:0] msi_width;

	IBUFDS_GTE2 refclk_buf (.I(pcie_refclk_p), .IB(pcie_refclk_n), .CEB(1'b0), .O(refclk),
		.ODIV2());

	/* user_rst_n: perst_n and the MMCM's lock, in user_clk */
	wire rst_in = pcie_perst_n && mmcm_lock;

	am_sync s_rst (.clk(aclk), .rst_n(rst_in), .d(1'b1), .q(user_rst_n));

	assign user_clk = aclk;

	/* The bridge's master (128 bit), before the split */
	wire [31:0] b_awaddr, b_araddr;
	wire [7:0] b_awlen, b_arlen;
	wire [2:0] b_awsize, b_arsize, b_awprot, b_arprot;
	wire [1:0] b_awburst, b_arburst, b_bresp, b_rresp;
	wire [3:0] b_awcache, b_arcache;
	wire b_awlock, b_arlock, b_awvalid, b_awready, b_wlast, b_wvalid, b_wready, b_bvalid;
	wire b_bready, b_arvalid, b_arready, b_rlast, b_rvalid, b_rready;
	wire [127:0] b_wdata, b_rdata;
	wire [15:0] b_wstrb;
	/* The MSI request */
	reg msi_q = 1'b0;
	reg ack_q = 1'b0;

	atg_kc705_pcie_ip bridge (
		.axi_aresetn(pcie_perst_n), .user_link_up(link_up), .axi_aclk_out(aclk),
		.axi_ctl_aclk_out(ctl_aclk), .mmcm_lock(mmcm_lock), .interrupt_out(irq_out),
		.INTX_MSI_Request(msi_q), .INTX_MSI_Grant(intx_grant), .MSI_enable(msi_en),
		.MSI_Vector_Num(5'd0), .MSI_Vector_Width(msi_width),
		.s_axi_awid(s_awid), .s_axi_awaddr(s_awaddr), .s_axi_awregion(4'd0),
		.s_axi_awlen(s_awlen), .s_axi_awsize(s_awsize), .s_axi_awburst(s_awburst),
		.s_axi_awvalid(s_awvalid), .s_axi_awready(s_awready), .s_axi_wdata(s_wdata),
		.s_axi_wstrb(s_wstrb), .s_axi_wlast(s_wlast), .s_axi_wvalid(s_wvalid),
		.s_axi_wready(s_wready), .s_axi_bid(s_bid), .s_axi_bresp(s_bresp),
		.s_axi_bvalid(s_bvalid), .s_axi_bready(s_bready), .s_axi_arid(s_arid),
		.s_axi_araddr(s_araddr), .s_axi_arregion(4'd0), .s_axi_arlen(s_arlen),
		.s_axi_arsize(s_arsize), .s_axi_arburst(s_arburst), .s_axi_arvalid(s_arvalid),
		.s_axi_arready(s_arready), .s_axi_rid(s_rid), .s_axi_rdata(s_rdata),
		.s_axi_rresp(s_rresp), .s_axi_rlast(s_rlast), .s_axi_rvalid(s_rvalid),
		.s_axi_rready(s_rready),
		.m_axi_awaddr(b_awaddr), .m_axi_awlen(b_awlen), .m_axi_awsize(b_awsize),
		.m_axi_awburst(b_awburst), .m_axi_awprot(b_awprot), .m_axi_awvalid(b_awvalid),
		.m_axi_awready(b_awready), .m_axi_awlock(b_awlock), .m_axi_awcache(b_awcache),
		.m_axi_wdata(b_wdata), .m_axi_wstrb(b_wstrb), .m_axi_wlast(b_wlast),
		.m_axi_wvalid(b_wvalid), .m_axi_wready(b_wready), .m_axi_bresp(b_bresp),
		.m_axi_bvalid(b_bvalid), .m_axi_bready(b_bready), .m_axi_araddr(b_araddr),
		.m_axi_arlen(b_arlen), .m_axi_arsize(b_arsize), .m_axi_arburst(b_arburst),
		.m_axi_arprot(b_arprot), .m_axi_arvalid(b_arvalid), .m_axi_arready(b_arready),
		.m_axi_arlock(b_arlock), .m_axi_arcache(b_arcache), .m_axi_rdata(b_rdata),
		.m_axi_rresp(b_rresp), .m_axi_rlast(b_rlast), .m_axi_rvalid(b_rvalid),
		.m_axi_rready(b_rready),
		.pci_exp_txp(pcie_txp), .pci_exp_txn(pcie_txn), .pci_exp_rxp(pcie_rxp),
		.pci_exp_rxn(pcie_rxn), .REFCLK(refclk),
		.s_axi_ctl_awaddr(32'd0), .s_axi_ctl_awvalid(1'b0), .s_axi_ctl_awready(),
		.s_axi_ctl_wdata(32'd0), .s_axi_ctl_wstrb(4'd0), .s_axi_ctl_wvalid(1'b0),
		.s_axi_ctl_wready(), .s_axi_ctl_bresp(), .s_axi_ctl_bvalid(), .s_axi_ctl_bready(1'b1),
		.s_axi_ctl_araddr(32'd0), .s_axi_ctl_arvalid(1'b0), .s_axi_ctl_arready(),
		.s_axi_ctl_rdata(), .s_axi_ctl_rresp(), .s_axi_ctl_rvalid(), .s_axi_ctl_rready(1'b1)
	);

	/* MSI: one request at a time. */
	always @(posedge aclk) begin
		ack_q <= 1'b0;
		if (!user_rst_n)
			msi_q <= 1'b0;
		else if (msi_q) begin
			if (intx_grant) begin
				msi_q <= 1'b0;
				ack_q <= 1'b1;
			end
		end else if (msi_en && msi_req && !ack_q)
			msi_q <= 1'b1;
	end
	assign msi_ack = ack_q;

	/* The split: M00 BAR0, M01 BAR2 (packed: [0] and [1]) */
	wire [1:0] x_awid, x_arid, x_awvalid, x_awready, x_wlast, x_wvalid, x_wready, x_bid;
	wire [1:0] x_bvalid, x_bready, x_arvalid, x_arready, x_rid, x_rlast, x_rvalid, x_rready;
	wire [63:0] x_awaddr, x_araddr;
	wire [15:0] x_awlen, x_arlen;
	wire [5:0] x_awsize, x_arsize, x_awprot, x_arprot;
	wire [3:0] x_awburst, x_arburst, x_bresp, x_rresp;
	wire [1:0] x_awlock, x_arlock;
	wire [7:0] x_awcache, x_arcache, x_awregion, x_arregion, x_awqos, x_arqos;
	wire [255:0] x_wdata, x_rdata;
	wire [31:0] x_wstrb;
	wire xs_bid, xs_rid;

	atg_kc705_bar_xbar split (
		.aclk(aclk), .aresetn(user_rst_n),
		.s_axi_awid(1'b0), .s_axi_awaddr(b_awaddr), .s_axi_awlen(b_awlen),
		.s_axi_awsize(b_awsize), .s_axi_awburst(b_awburst), .s_axi_awlock(b_awlock),
		.s_axi_awcache(b_awcache), .s_axi_awprot(b_awprot), .s_axi_awqos(4'd0),
		.s_axi_awvalid(b_awvalid), .s_axi_awready(b_awready), .s_axi_wdata(b_wdata),
		.s_axi_wstrb(b_wstrb), .s_axi_wlast(b_wlast), .s_axi_wvalid(b_wvalid),
		.s_axi_wready(b_wready), .s_axi_bid(xs_bid), .s_axi_bresp(b_bresp),
		.s_axi_bvalid(b_bvalid), .s_axi_bready(b_bready), .s_axi_arid(1'b0),
		.s_axi_araddr(b_araddr), .s_axi_arlen(b_arlen), .s_axi_arsize(b_arsize),
		.s_axi_arburst(b_arburst), .s_axi_arlock(b_arlock), .s_axi_arcache(b_arcache),
		.s_axi_arprot(b_arprot), .s_axi_arqos(4'd0), .s_axi_arvalid(b_arvalid),
		.s_axi_arready(b_arready), .s_axi_rid(xs_rid), .s_axi_rdata(b_rdata),
		.s_axi_rresp(b_rresp), .s_axi_rlast(b_rlast), .s_axi_rvalid(b_rvalid),
		.s_axi_rready(b_rready),
		.m_axi_awid(x_awid), .m_axi_awaddr(x_awaddr), .m_axi_awlen(x_awlen),
		.m_axi_awsize(x_awsize), .m_axi_awburst(x_awburst), .m_axi_awlock(x_awlock),
		.m_axi_awcache(x_awcache), .m_axi_awprot(x_awprot), .m_axi_awregion(x_awregion),
		.m_axi_awqos(x_awqos), .m_axi_awvalid(x_awvalid), .m_axi_awready(x_awready),
		.m_axi_wdata(x_wdata), .m_axi_wstrb(x_wstrb), .m_axi_wlast(x_wlast),
		.m_axi_wvalid(x_wvalid), .m_axi_wready(x_wready), .m_axi_bid(x_bid),
		.m_axi_bresp(x_bresp), .m_axi_bvalid(x_bvalid), .m_axi_bready(x_bready),
		.m_axi_arid(x_arid), .m_axi_araddr(x_araddr), .m_axi_arlen(x_arlen),
		.m_axi_arsize(x_arsize), .m_axi_arburst(x_arburst), .m_axi_arlock(x_arlock),
		.m_axi_arcache(x_arcache), .m_axi_arprot(x_arprot), .m_axi_arregion(x_arregion),
		.m_axi_arqos(x_arqos), .m_axi_arvalid(x_arvalid), .m_axi_arready(x_arready),
		.m_axi_rid(x_rid), .m_axi_rdata(x_rdata), .m_axi_rresp(x_rresp),
		.m_axi_rlast(x_rlast), .m_axi_rvalid(x_rvalid), .m_axi_rready(x_rready)
	);

	/* M00 -> 32 bit: BAR0 */
	wire [31:0] d_awaddr, d_araddr;
	wire [7:0] d_awlen;
	wire [2:0] d_awsize, d_arsize, d_awprot, d_arprot;
	wire [1:0] d_awburst, d_arburst;
	wire [3:0] d_awcache, d_arcache, d_awregion, d_arregion, d_awqos, d_arqos;
	wire d_awlock, d_arlock;

	atg_kc705_bar0_dn bar0_dn (
		.s_axi_aclk(aclk), .s_axi_aresetn(user_rst_n),
		.s_axi_awid(x_awid[0]), .s_axi_awaddr(x_awaddr[31:0]), .s_axi_awlen(x_awlen[7:0]),
		.s_axi_awsize(x_awsize[2:0]), .s_axi_awburst(x_awburst[1:0]),
		.s_axi_awlock(x_awlock[0]), .s_axi_awcache(x_awcache[3:0]),
		.s_axi_awprot(x_awprot[2:0]), .s_axi_awregion(x_awregion[3:0]),
		.s_axi_awqos(x_awqos[3:0]), .s_axi_awvalid(x_awvalid[0]),
		.s_axi_awready(x_awready[0]), .s_axi_wdata(x_wdata[127:0]),
		.s_axi_wstrb(x_wstrb[15:0]), .s_axi_wlast(x_wlast[0]), .s_axi_wvalid(x_wvalid[0]),
		.s_axi_wready(x_wready[0]), .s_axi_bid(x_bid[0]), .s_axi_bresp(x_bresp[1:0]),
		.s_axi_bvalid(x_bvalid[0]), .s_axi_bready(x_bready[0]), .s_axi_arid(x_arid[0]),
		.s_axi_araddr(x_araddr[31:0]), .s_axi_arlen(x_arlen[7:0]),
		.s_axi_arsize(x_arsize[2:0]), .s_axi_arburst(x_arburst[1:0]),
		.s_axi_arlock(x_arlock[0]), .s_axi_arcache(x_arcache[3:0]),
		.s_axi_arprot(x_arprot[2:0]), .s_axi_arregion(x_arregion[3:0]),
		.s_axi_arqos(x_arqos[3:0]), .s_axi_arvalid(x_arvalid[0]),
		.s_axi_arready(x_arready[0]), .s_axi_rid(x_rid[0]), .s_axi_rdata(x_rdata[127:0]),
		.s_axi_rresp(x_rresp[1:0]), .s_axi_rlast(x_rlast[0]), .s_axi_rvalid(x_rvalid[0]),
		.s_axi_rready(x_rready[0]),
		.m_axi_awaddr(d_awaddr), .m_axi_awlen(d_awlen), .m_axi_awsize(d_awsize),
		.m_axi_awburst(d_awburst), .m_axi_awlock(d_awlock), .m_axi_awcache(d_awcache),
		.m_axi_awprot(d_awprot), .m_axi_awregion(d_awregion), .m_axi_awqos(d_awqos),
		.m_axi_awvalid(m0_awvalid), .m_axi_awready(m0_awready), .m_axi_wdata(m0_wdata),
		.m_axi_wstrb(m0_wstrb), .m_axi_wlast(m0_wlast), .m_axi_wvalid(m0_wvalid),
		.m_axi_wready(m0_wready), .m_axi_bresp(m0_bresp), .m_axi_bvalid(m0_bvalid),
		.m_axi_bready(m0_bready), .m_axi_araddr(d_araddr), .m_axi_arlen(m0_arlen),
		.m_axi_arsize(d_arsize), .m_axi_arburst(d_arburst), .m_axi_arlock(d_arlock),
		.m_axi_arcache(d_arcache), .m_axi_arprot(d_arprot), .m_axi_arregion(d_arregion),
		.m_axi_arqos(d_arqos), .m_axi_arvalid(m0_arvalid), .m_axi_arready(m0_arready),
		.m_axi_rdata(m0_rdata), .m_axi_rresp(m0_rresp), .m_axi_rlast(m0_rlast),
		.m_axi_rvalid(m0_rvalid), .m_axi_rready(m0_rready)
	);
	assign m0_awaddr = d_awaddr[16:0];
	assign m0_araddr = d_araddr[16:0];
	assign m0_awid = 4'd0;
	assign m0_arid = 4'd0;

	/* M01: BAR2 */
	assign m2_awaddr = x_awaddr[57:32];
	assign m2_awid = {3'd0, x_awid[1]};
	assign m2_awlen = x_awlen[15:8];
	assign m2_awsize = x_awsize[5:3];
	assign m2_awburst = x_awburst[3:2];
	assign m2_awvalid = x_awvalid[1];
	assign x_awready[1] = m2_awready;
	assign m2_wdata = x_wdata[255:128];
	assign m2_wstrb = x_wstrb[31:16];
	assign m2_wlast = x_wlast[1];
	assign m2_wvalid = x_wvalid[1];
	assign x_wready[1] = m2_wready;
	assign x_bid[1] = m2_bid[0];
	assign x_bresp[3:2] = m2_bresp;
	assign x_bvalid[1] = m2_bvalid;
	assign m2_bready = x_bready[1];
	assign m2_araddr = x_araddr[57:32];
	assign m2_arid = {3'd0, x_arid[1]};
	assign m2_arlen = x_arlen[15:8];
	assign m2_arsize = x_arsize[5:3];
	assign m2_arburst = x_arburst[3:2];
	assign m2_arvalid = x_arvalid[1];
	assign x_arready[1] = m2_arready;
	assign x_rid[1] = m2_rid[0];
	assign x_rdata[255:128] = m2_rdata;
	assign x_rresp[3:2] = m2_rresp;
	assign x_rlast[1] = m2_rlast;
	assign x_rvalid[1] = m2_rvalid;
	assign m2_rready = x_rready[1];

	wire unused_ok = &{1'b0, ctl_aclk, irq_out, msi_width, xs_bid, xs_rid, d_awaddr[31:17],
		d_araddr[31:17], d_awlen, d_awsize, d_awburst, d_awlock, d_awcache, d_awprot,
		d_awregion, d_awqos, d_arsize, d_arburst, d_arlock, d_arcache, d_arprot, d_arregion,
		d_arqos, x_awaddr[63:58], x_araddr[63:58], x_awaddr[31:0] & 32'd0, m0_bid, m0_rid,
		m2_bid[3:1], m2_rid[3:1], x_awlock[1], x_arlock[1], x_awcache[7:4], x_arcache[7:4],
		x_awprot[5:3], x_arprot[5:3], x_awregion[7:4], x_arregion[7:4], x_awqos[7:4],
		x_arqos[7:4]};
endmodule

`default_nettype wire
